def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    isolated_sets = []  # Initialize an empty list to store isolated sets
    stack = []  # Use a stack to track opening and closing parentheses

    for char in paren_string:
        if char == '(':
            stack.append('')
        elif char == ')':
            isolated_sets.append(''.join(stack))
            stack.pop()
        else:
            for i in range(len(stack)):
                stack[i] += char

    return isolated_sets
